// Manifest-driven module loading, bn service.mjs style.
// modules.json (generated by tools/gen_manifest.mjs) looks like:
//   { "files": {"automata.grammar_tools": "automata/grammar_tools.lua"},
//     "deps":  {"automata.init": ["automata.basic", ...]} }
// The loader fetches the entry module's transitive dependency closure,
// then registers all of them via package.preload — require stays sync.

export function normModuleName(name) {
    return String(name).replace(/\.lua$/, '').replace(/\//g, '.');
}

export async function loadManifest(luaRoot, fetchText) {
    const url = String(luaRoot).replace(/\/?$/, '/') + 'modules.json';
    const manifest = JSON.parse(await fetchText(url));
    manifest.deps = manifest.deps || {};
    return manifest;
}

// transitive dependency closure of `entry` (post-order, entry last);
// deps that have no file in the manifest are ignored
export function depsClosure(manifest, entry) {
    entry = normModuleName(entry);
    const seen = new Set(), out = [];
    (function visit(n) {
        if (seen.has(n)) return;
        seen.add(n);
        for (const d of manifest.deps[n] || []) visit(d);
        if (manifest.files[n]) out.push(n);
    })(entry);
    return out;
}

// Serialised ensure(entry): fetches + preloads the dependency closure
// once; later entries only fetch what is not registered yet.  Jobs are
// chained so concurrent ensures cannot double-fetch, and a failed job
// does not mark anything registered — the next ensure retries it.
export function makeLoader(registerSources, fetchText, luaRoot, manifest) {
    const registered = new Set();
    let tail = Promise.resolve();
    return function ensure(entry) {
        const name = normModuleName(entry);
        if (!manifest.files[name])
            return Promise.reject(
                new Error('module_loader: unknown module ' + name));
        const mods = depsClosure(manifest, name)
            .filter(m => !registered.has(m));
        if (mods.length === 0) return tail;
        const job = tail.then(async () => {
            const fetched = {};
            await Promise.all(mods.map(async m => {
                const url = String(luaRoot).replace(/\/?$/, '/')
                    + manifest.files[m];
                fetched[m] = await fetchText(url);
            }));
            registerSources(fetched);
            mods.forEach(m => registered.add(m));
        });
        tail = job.catch(() => { });
        return job;
    };
}
